NavigationSuiteScaffold(
    navigationSuiteItems = {
        destinations.forEachIndexed { index, (label, icon) ->
            item(
                selected = selected == index,
                onClick = { selected = index },
                icon = { MonarchIcon(icon, contentDescription = null) },
                label = { Text(label) },
            )
        }
    },
    modifier = Modifier.height(MonarchTheme.spacing.space24 * 2),
) {
    MonarchText(text = destinations[selected].first)
}
